#include <iostream>
#include <vector>
using namespace std;

vector<long long> memo(100, -1);

long long fib(int n) {
    if (n <= 1) return n; // Base case
    if (memo[n] != -1) return memo[n]; // Lay tu cache
    return memo[n] = fib(n - 1) + fib(n - 2);
}

int main() {
    cout << "Fib(50) = " << fib(50) << endl;
    return 0;
}

